/*
 * p8_font.h -- the REAL PICO-8 system font, extracted from the
 * cart's font sheet by tools/gen_font.py (do not edit by hand).
 * Each glyph is 5 rows; the low 3 bits of each row are the pixels
 * (bit2 = left column).  print() advances 4px per char.
 *
 * PICO-8 quirk kept: a..z cells hold the standard glyphs, A..Z the
 * puny small-caps -- lowercase text renders exactly like PICO-8.
 */
